#!/usr/bin/env node
/**
 * Generates rest/library.http from the Query Library, for the VS Code
 * "REST Client" extension (humao.rest-client). Click "Send Request" above any query.
 */
import fs from 'node:fs';
import path from 'node:path';
import { config } from '../server/config.js';
import { queryLibrary } from '../sql-library/queryLibrary.js';
import { requestsOf } from '../sql-library/runner.js';

const out = path.join(config.root, 'rest', 'library.http');
const lines = [
  '# Service Request Query Library — ArcGIS REST requests',
  '# Generated by `npm run build:http`. Start the server first: `npm start`.',
  '# Point @layer at a real FeatureServer layer to run the same requests there.',
  '',
  `@layer = http://127.0.0.1:${config.port}/arcgis/rest/services/${config.serviceName}/FeatureServer/0`,
  '',
];
for (const q of queryLibrary) {
  for (const r of requestsOf(q)) {
    lines.push(`### Q${q.id}${r.name !== 'main' ? ` (${r.name})` : ''} — ${q.question}  [${q.portability}]`);
    if (q.transform) lines.push(`# client-side transform: ${[q.transform].flat().map((t) => t.type).join(' -> ')}`);
    lines.push('POST {{layer}}/query', 'Content-Type: application/x-www-form-urlencoded', '');
    const params = { f: 'pjson', ...r.params };
    lines.push(Object.entries(params).map(([k, v], i) => `${i ? '&' : ''}${k}=${encodeURIComponent(typeof v === 'object' ? JSON.stringify(v) : String(v))}`).join('\n'));
    lines.push('');
  }
}
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, lines.join('\n'));
console.log(`Wrote ${path.relative(process.cwd(), out)}`);
